<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { applySceneTheme, currentSceneId } from '@/core/scenes'
import { readSession } from '@/core/auth'
import { searchAll, type SearchResult } from '@/domain/search'
import { undoLast } from '@/core/undo'

const route = useRoute(); const router = useRouter()
const drawer = ref(false); const dark = ref(document.documentElement.classList.contains('dark')); const searchOpen = ref(false); const searchQuery = ref(''); const searchTick = ref(0); const undoVisible = ref(false)
const isMobile = ref(window.innerWidth < 900)
const active = computed(() => route.name === 'home' || route.name === 'today' ? 'today' : route.name === 'capture' ? 'capture' : route.name === 'review' ? 'review' : route.name === 'matters' || route.name === 'matter' || route.name === 'cases' || route.name === 'case' ? 'matters' : '')
const initials = computed(() => (readSession()?.u?.[0] || 'C').toUpperCase())
const searchResults = computed(() => { void searchTick.value; return searchAll(searchQuery.value, 8) })
function go(path: string) { drawer.value = false; router.push(path) }
function openSearch() { searchOpen.value = true; searchQuery.value = ''; requestAnimationFrame(() => document.querySelector<HTMLInputElement>('.global-search input')?.focus()) }
function closeSearch() { searchOpen.value = false }
function goSearchResult(item: SearchResult) { closeSearch(); router.push(item.route) }
function resize() { isMobile.value = window.innerWidth < 900 }
function toggleTheme() { dark.value = !dark.value; document.documentElement.classList.toggle('dark', dark.value); localStorage.setItem('b_theme', dark.value ? 'dark' : 'light') }
function onKeydown(event: KeyboardEvent) { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); openSearch() } else if (event.key === 'Escape') closeSearch() }
function onDataSynced() { searchTick.value++ }
function onUndoAvailable() { undoVisible.value = true; window.setTimeout(() => { undoVisible.value = false }, 8000) }
function undo() { undoVisible.value = !undoLast(); }
onMounted(() => { applySceneTheme(currentSceneId()); window.addEventListener('resize', resize); window.addEventListener('keydown', onKeydown); window.addEventListener('beryl-data-synced', onDataSynced); window.addEventListener('beryl-undo-available', onUndoAvailable) })
onUnmounted(() => { window.removeEventListener('resize', resize); window.removeEventListener('keydown', onKeydown); window.removeEventListener('beryl-data-synced', onDataSynced); window.removeEventListener('beryl-undo-available', onUndoAvailable) })
</script>

<template>
  <div class="app-shell">
    <aside v-if="!isMobile" class="sidebar">
      <button class="brand" aria-label="返回 Today" @click="go('/app/today')"><span class="brand-mark" aria-hidden="true">C</span><span><b class="font-title">Calmy</b><small>现实行动系统</small></span></button>
      <nav class="primary-nav" aria-label="主导航">
        <button :class="{ on: active === 'today' }" :aria-current="active === 'today' ? 'page' : undefined" @click="go('/app/today')"><i aria-hidden="true">◷</i>Today</button>
        <button :class="{ on: active === 'capture' }" :aria-current="active === 'capture' ? 'page' : undefined" @click="go('/app/capture')"><i aria-hidden="true">↓</i>Capture</button>
        <button :class="{ on: active === 'matters' }" :aria-current="active === 'matters' ? 'page' : undefined" @click="go('/app/matters')"><i aria-hidden="true">◎</i>课题</button>
        <button :class="{ on: active === 'review' }" :aria-current="active === 'review' ? 'page' : undefined" @click="go('/app/review')"><i aria-hidden="true">↺</i>复盘</button>
      </nav>
      <div class="sidebar-foot"><button aria-label="搜索课题" @click="openSearch"><span aria-hidden="true">⌕</span>　搜索 <kbd>Ctrl K</kbd></button><button aria-label="打开更多入口" @click="drawer = true"><span aria-hidden="true">⋯</span>　更多</button><button :aria-label="dark ? '切换到浅色界面' : '切换到深色界面'" @click="toggleTheme"><span aria-hidden="true">{{ dark ? '☀' : '◐' }}</span> {{ dark ? '浅色界面' : '深色界面' }}</button><button aria-label="设置与同步" @click="go('/app/admin')"><span aria-hidden="true">{{ initials }}</span>　设置与同步</button></div>
    </aside>

    <header v-else class="mobile-header"><button class="brand compact" aria-label="返回 Today" @click="go('/app/today')"><span class="brand-mark" aria-hidden="true">C</span><b class="font-title">Calmy</b></button><div><button class="search-btn" aria-label="搜索课题" @click="openSearch"><span aria-hidden="true">⌕</span></button><button class="menu" aria-label="打开更多入口" @click="drawer = true"><span aria-hidden="true">☰</span></button></div></header>
    <main class="page-container"><RouterView /></main>
    <nav v-if="isMobile" class="bottom-nav" aria-label="移动端主导航"><button :class="{ on: active === 'today' }" :aria-current="active === 'today' ? 'page' : undefined" @click="go('/app/today')"><span aria-hidden="true">◷</span>Today</button><button :class="{ on: active === 'matters' }" :aria-current="active === 'matters' ? 'page' : undefined" @click="go('/app/matters')"><span aria-hidden="true">◎</span>课题</button><button :class="{ on: active === 'capture' }" :aria-current="active === 'capture' ? 'page' : undefined" @click="go('/app/capture')"><span aria-hidden="true">↓</span>Capture</button><button :class="{ on: active === 'review' }" :aria-current="active === 'review' ? 'page' : undefined" @click="go('/app/review')"><span aria-hidden="true">↺</span>复盘</button><button aria-label="更多导航" @click="drawer = true"><span aria-hidden="true">⋯</span>更多</button></nav>
    <el-drawer v-model="drawer" direction="rtl" size="min(84vw,330px)" :with-header="false"><div class="drawer"><button class="brand" aria-label="返回 Today" @click="go('/app/today')"><span class="brand-mark" aria-hidden="true">C</span><span><b class="font-title">Calmy</b><small>现实行动系统</small></span></button><nav class="drawer-links" aria-label="更多入口"><button @click="openSearch">⌕ 搜索课题</button><p>查找与历史</p><button @click="go('/app/people')">♧ 人物上下文</button><button @click="go('/app/library')">▤ 资料与记录</button><button @click="go('/app/calendar')">▦ 日历视图</button><p>数据与外观</p><button @click="toggleTheme">{{ dark ? '☀' : '◐' }} 切换外观</button><button @click="go('/app/admin')">⚙ 设置与同步</button><p>实验功能</p><button @click="go('/app/graph')">⌘ 图谱（实验）</button><button @click="go('/scene')">◌ 场景（实验）</button><button @click="go('/app/module/inbox')">↓ 旧收集箱（兼容）</button></nav></div></el-drawer>
    <div v-if="searchOpen" class="search-overlay" role="dialog" aria-modal="true" aria-label="搜索课题" @click.self="closeSearch"><div class="search-panel beryl-card"><div class="search-head"><span aria-hidden="true">⌕</span><el-input v-model="searchQuery" class="global-search" aria-label="搜索课题" placeholder="搜索 Matter、行动、记录或人物…" /><button aria-label="关闭搜索" @click="closeSearch">Esc</button></div><div class="search-results"><button v-for="item in searchResults" :key="`${item.type}:${item.id}`" @click="goSearchResult(item)"><span class="result-icon" aria-hidden="true">{{ item.icon }}</span><span class="result-copy"><b>{{ item.title }}</b><small>{{ item.typeLabel }} · {{ item.summary }}</small></span><i aria-hidden="true">→</i></button><p v-if="!searchResults.length" class="no-results">没有匹配的内容</p></div></div></div>
    <div v-if="undoVisible" class="undo-bar"><span>已删除一条记录</span><button @click="undo">撤销</button></div>
  </div>
</template>

